def kind_to_types(apps, schema_editor):
    """Ancien type unique -> nouveaux types multiples ; les rentrées doctorales ont désormais leur propre type."""
    Event = apps.get_model("events", "Event")
    for event in Event.objects.all():
        codes = [event.kind]
        if "rentree" in event.slug or "welcome-day" in event.slug:
            codes = ["rentree"]
        event.types = "," + ",".join(codes) + ","
        event.save(update_fields=["types"])


